Q: Converting a hex string to a byte array A: <p>this worked for me, hope you will find it helpful too:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;cstdlib&gt;
#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;vector&gt;

using u8 = unsigned char;

std::vector&lt;u8&gt; hexToBytes(const std::string&amp; hex)
{
  std::vector&lt;u8&gt; buf {};

  u8 val {};
  for (int i = 0; i != hex.length(); i += 2) {
    char st[] = { hex[i], hex[i + 1], 0 };

    char* end;
    val = static_cast&lt;u8&gt;(strtoul(st, &amp;end, 16));
    buf.push_back(val);
  }

  return buf;
}

std::string bytesToHex(const std::vector&lt;u8&gt;&amp; data)
{
  std::string res {};
  char s[3] {};
  for (u8 byte : data) {
    snprintf(s, sizeof(s), &quot;%02hhx&quot;, byte);
    res.append(s);
  }
  return res;
}

/*
        you can test it like so:
*/

int main(int argc, char const* argv[])
{
  // test 1: Hex to Bytes
  std::string hexInput = &quot;48656c6c6f&quot;; // &quot;Hello&quot; in hex
  std::vector&lt;u8&gt; bytes = hexToBytes(hexInput);

  std::cout &lt;&lt; &quot;hex input: &quot; &lt;&lt; hexInput &lt;&lt; std::endl;
  std::cout &lt;&lt; &quot;decoded chars: &quot;;
  for (u8 b : bytes) {
    std::cout &lt;&lt; (char)b;
  }
  std::cout &lt;&lt; &quot;\n\n&quot;;

  // test 2: Bytes to Hex
  std::vector&lt;u8&gt; dataToEncode = { 0xde, 0xad, 0xbe, 0xef, 0x01 };
  std::string hexOutput = bytesToHex(dataToEncode);

  std::cout &lt;&lt; &quot;byte input: { 0xDE, 0xAD, 0xBE, 0xEF, 0x01 }&quot; &lt;&lt; std::endl;
  std::cout &lt;&lt; &quot;encoded hex: &quot; &lt;&lt; hexOutput &lt;&lt; std::endl;

  // validation
  if (hexToBytes(bytesToHex(dataToEncode)) == dataToEncode) {
    std::cout &lt;&lt; &quot;\ntest passed!&quot; &lt;&lt; std::endl;
  }

  return 0;
}
</code></pre>

Q: How to Inject AppDbContext in Wpf core Applications using caliburn micro A: <p>You could try using <code>RegisterHandler</code> method on <code>SimpleContainer</code> - it allows you to define &quot;factory method&quot; for serving objects of specified type, instead of <code>Instance</code> and <code>PerRequest</code> method</p>
<pre><code>_container.RegisterHandler(
    typeof(AppDbContext),
    &quot;DataAccess&quot;,
    c =&gt;
    {
        var options = new DbContextOptionsBuilder&lt;AppDbContext&gt;()
            .UseJet(@&quot;Provider=Microsoft.ACE.OLEDB.12.0;Data Source=F:\AccessDatabase      \TestDatabase1.accdb;&quot;)
            .Options;
        return new AppDbContext(options);
    });
</code></pre>
<p>Then it correctly resolves <code>DataAccess</code> constructor argument without no further adjustments.</p>
